/**
 * The Palais plaque, drawn for the profile: the same rounded frame the
 * portfolio's page titles wear (portfolio/src/index.css, .page-ribbon) — the
 * floral's own stone inside a gold rim inside a cream one, with a posy of
 * Molly's flowers tucked behind each end.
 *
 * The flowers travel inside the picture: GitHub serves README images through
 * its own proxy, and anything pointing somewhere else comes out blank.
 * Generated by assets/makePlaque.mjs from portfolio/public/palais/blooms.
 */

const CREAM = "#fffaf0";
const FONT = "'Roboto Mono','SF Mono',SFMono-Regular,ui-monospace,Menlo,monospace";

/** the stone each pattern lends the plaque, from palais/florals.ts */
export const JEWELS: Record<string, string> = {
  teal: "#1a8f8a",
  pink: "#c43b6e",
  "black-gold": "#d8b55c",
  green: "#2f7a3d",
  maroon: "#a8244f",
  purple: "#6a4bb0",
  orange: "#d2651b",
  yellow: "#c9a227",
  cream: "#c0392b",
  "red-toile": "#8f1420",
};

const POSY = [
  { uri: "data:image/webp;base64,", x: 2, y: 40, w: 48, rot: -18 },
  { uri: "data:image/webp;base64,", x: 20, y: 8, w: 46, rot: 12 },
  { uri: "data:image/webp;base64,", x: 54, y: 40, w: 34, rot: -10 },
  { uri: "data:image/webp;base64,", x: 52, y: 2, w: 38, rot: 20 },
];

const posy = (box: number) =>
  POSY.map((p) => {
    const w = (p.w / 100) * box;
    const x = (p.x / 100) * box + w / 2;
    const y = (p.y / 100) * box + w / 2;
    return `<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${p.rot})"><image x="${(-w / 2).toFixed(1)}" y="${(-w / 2).toFixed(1)}" width="${w.toFixed(1)}" height="${w.toFixed(1)}" href="${p.uri}"/></g>`;
  }).join("");

export interface Plaque {
  /** one line, or a big line and a small one under it */
  lines: [string] | [string, string];
  /** the stone it is filled with */
  jewel: string;
  /** its rim */
  gold: string;
  label: string;
  width?: number;
}

export function plaque({ lines, jewel, gold, label, width = 360 }: Plaque): string {
  const h = 96, box = 66, pad = 30;
  const px = pad, py = 18, pw = width - pad * 2, ph = h - 36, r = ph / 2, mid = width / 2;
  const writing =
    lines.length === 1
      ? `<text x="${mid}" y="${py + ph / 2 + 7}" text-anchor="middle" font-family="${FONT}" font-size="21" font-weight="700" fill="${CREAM}" filter="url(#under)">${lines[0]}</text>`
      : `<text x="${mid}" y="${py + ph / 2 - 2}" text-anchor="middle" font-family="${FONT}" font-size="19" font-weight="700" fill="${CREAM}" filter="url(#under)">${lines[0]}</text>
    <text x="${mid}" y="${py + ph / 2 + 16}" text-anchor="middle" font-family="${FONT}" font-size="9" font-weight="600" letter-spacing="1.4" fill="${CREAM}" fill-opacity=".92">${lines[1]}</text>`;

  return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${width}" height="${h}" viewBox="0 0 ${width} ${h}" role="img" aria-label="${label}">
  <defs>
    <filter id="under" x="-20%" y="-60%" width="140%" height="260%">
      <feDropShadow dx="0" dy="2" stdDeviation="0" flood-color="#281e0e" flood-opacity=".35"/>
    </filter>
    <filter id="lift" x="-30%" y="-60%" width="160%" height="260%">
      <feDropShadow dx="0" dy="6" stdDeviation="5" flood-color="#46320a" flood-opacity=".3"/>
    </filter>
    <g id="posy">${posy(box)}</g>
  </defs>
  <g filter="url(#lift)">
    <rect x="${px - 5.5}" y="${py - 5.5}" width="${pw + 11}" height="${ph + 11}" rx="${r + 5.5}" fill="none" stroke="${gold}" stroke-opacity=".8" stroke-width="1.5"/>
    <rect x="${px - 4}" y="${py - 4}" width="${pw + 8}" height="${ph + 8}" rx="${r + 4}" fill="none" stroke="${CREAM}" stroke-width="4"/>
    <rect x="${px}" y="${py}" width="${pw}" height="${ph}" rx="${r}" fill="${jewel}"/>
    <rect x="${px + 1.5}" y="${py + 1.5}" width="${pw - 3}" height="${ph - 3}" rx="${r - 1.5}" fill="none" stroke="${gold}" stroke-width="3"/>
    <rect x="${px + 4.5}" y="${py + 4.5}" width="${pw - 9}" height="${ph - 9}" rx="${r - 4.5}" fill="none" stroke="${CREAM}" stroke-opacity=".5" stroke-width="3"/>
  </g>
  <use xlink:href="#posy" x="0" y="${(h - box) / 2}"/>
  <g transform="translate(${width} 0) scale(-1 1)"><use xlink:href="#posy" x="0" y="${(h - box) / 2}"/></g>
  ${writing}
</svg>`;
}
